    int first = bb.get(i) & 0xFF;
    int bytesNeeded = 0;
    if ((first & 0x80) == 0) {
        bytesNeeded = 1;
    } else if ((first & 0xE0) == 0xC0) {
        bytesNeeded = 2;
    } else if ((first & 0xF0) == 0xE0) {
        bytesNeeded = 3;
    } else if ((first & 0xF8) == 0xF0) {
        bytesNeeded = 4;
    }
    // If the byte sequence is incomplete or invalid, return the current index
    if (bytesNeeded == 0 || bytesNeeded > remaining) {
        return i;
    }
    // Extract the octets for the character
    byte[] octets = new byte[bytesNeeded];
    for (int k = 0; k < bytesNeeded; k++) {
        octets[k] = bb.get(i + k);
    }
    // Decode the octets as UTF‑8 and append to the StringBuilder
    try {
