    TreeNode<T> left = node.left;
    TreeNode<T> leftRight = left.right;

    // perform rotation
    left.right = node;
    node.left = leftRight;

    // update parents
    TreeNode<T> oldParent = node.parent;
    left.parent = oldParent;
    node.parent = left;
    if (leftRight != null) leftRight.parent = node;

    // reconnect with grandparent if exists
    if (oldParent != null) {
        if (oldParent.left == node) oldParent.left = left;
        else if (oldParent.right == node) oldParent.right = left;
    }
