private int parseEndOfLine(String headerPart,int end){
    // Validate input
    if (headerPart == null) {
        return -1;
    }
    int len = headerPart.length();
    if (end < 0 || end >= len) {
        return -1;
    }

    // Search for CRLF (\r\n) starting from 'end'
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i; // Return the index of the '\r' which starts the CRLF sequence
        }
    }
    return -1; // No CRLF found
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || end < 0){
        return -1;
    }
    // Ensure we don't start searching beyond the end of the string
    int startSearch = Math.min(end, headerPart.length() - 1);
    int idx = headerPart.indexOf("\r\n", startSearch);
    if (idx == -1) {
        // No CRLF found; indicate end of the string
        return headerPart.length();
    }
    return idx;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null){
        return -1;
    }
    int length = headerPart.length();
    int start = (end < 0) ? 0 : Math.min(end, length - 1);
    for(int i = start; i < length - 1; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    // Validate input
    if (headerPart == null || headerPart.isEmpty()) {
        return -1;
    }
    int length = headerPart.length();
    if (end < 0 || end >= length) {
        return -1;
    }
    // Search for CRLF sequence starting from the provided end index
    for (int i = end; i < length - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // If not found, return -1 to indicate no end of line was detected
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    try{
        if(headerPart == null){
            throw new IllegalArgumentException("headerPart cannot be null");
        }
        if(end < -1 || end >= headerPart.length()){
            throw new IllegalArgumentException("end index out of bounds");
        }
        int len = headerPart.length();
        for(int i = end + 1; i < len - 1; i++){
            if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
                return i;
            }
        }
        return -1;
    }catch(Exception e){
        throw new RuntimeException(e);
    }
}

