            }
            for (File f : files) {
                forceDeleteOnExit(f);
            }
            file.deleteOnExit();
        } else {
            file.deleteOnExit();
        }
    } catch (SecurityException e) {
        throw new IOException("Permission denied scheduling deletion for: " + file, e);
    }
}

