@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    try {
        // Collect vertices from resultMap into two partitions based on key prefix
        List<V> left = new ArrayList<>();
        List<V> right = new ArrayList<>();
        for (Map.Entry<String,V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            if (key != null && key.startsWith("L")) {
                left.add(entry.getValue());
            } else if (key != null && key.startsWith("R")) {
                right.add(entry.getValue());
            }
        }
        // If no explicit prefixes, split the set approximately in half
        if (left.isEmpty() && right.isEmpty()) {
            Iterator<V> it = resultMap.values().iterator();
            int count = 0;
            while (it.hasNext()) {
                V v = it.next();
                if (count % 2 == 0) left.add(v);
                else right.add(v);
                count++;
            }
        }
        // Add all vertices to the target graph
        for (V v : left) {
            target.addVertex(v);
        }
        for (V v : right) {
            target.addVertex(v);
        }
        // Create all cross edges to form a complete bipartite graph
        for (V lv : left) {
            for (V rv : right) {
                target.addEdge(lv, rv);
            }
        }
    } catch (Exception e) {
        // Log or handle exception as appropriate
        System.err.println("Error generating complete bipartite graph: " + e.getMessage());
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null) throw new IllegalArgumentException("target graph is null");
    if (resultMap == null) throw new IllegalArgumentException("resultMap is null");
    try{
        // Create two parts of the bipartite graph
        java.util.List<V> partA = new java.util.ArrayList<>();
        java.util.List<V> partB = new java.util.ArrayList<>();
        int sizeA = 3; // size of partition A
        int sizeB = 3; // size of partition B
        for (int i = 0; i < sizeA; i++){
            V v = (V)(Object)("A" + i);
            target.addVertex(v);
            partA.add(v);
        }
        for (int i = 0; i < sizeB; i++){
            V v = (V)(Object)("B" + i);
            target.addVertex(v);
            partB.add(v);
        }
        // Add edges between every vertex of partA and every vertex of partB
        for (V u : partA){
            for (V w : partB){
                target.addEdge(u, w);
            }
        }
        // Store a representative vertex from each partition into resultMap for reference
        if (!partA.isEmpty()){
            resultMap.put("partA", partA.get(0));
        }
        if (!partB.isEmpty()){
            resultMap.put("partB", partB.get(0));
        }
    } catch (Exception e){
        // Handle any unexpected runtime issue
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

