@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if(target == null) return;
    if(resultMap == null || resultMap.isEmpty()) return;
    // Add all vertices to the target graph
    for(V v : resultMap.values()){
        try{
            if(!target.containsVertex(v)){
                target.addVertex(v);
            }
        }catch(Exception e){
            // ignore; graph may not allow duplicate addition
        }
    }
    // Collect vertices into a list for deterministic ordering
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if(n < 2) return; // cannot form edges
    // Partition vertices into two halves: left and right sets
    int mid = n / 2;
    List<V> leftSet = vertices.subList(0, mid);
    List<V> rightSet = vertices.subList(mid, n);
    // Create edges between every pair of vertices from left and right sets
    for(V u : leftSet){
        for(V v : rightSet){
            try{
                if(target.getEdge(u, v) == null){
                    target.addEdge(u, v);
                }
            }catch(Exception e){
                // ignore; could be due to graph restrictions
            }
        }
    }
}

