protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        // If duration is non-positive just add the whole range once
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = current + maxDuration;
        long rangeEnd = next < 0 || next > end ? end : next; // handle overflow
        ranges.add(new TimeRange(current, rangeEnd));
        current = rangeEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if(start < 0 || end < 0){
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }
    if(start >= end){
        return new ArrayList<>();
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while(current < end){
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time.");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (end < start) {
        throw new IllegalArgumentException("end (" + end + ") must be greater than or equal to start (" + start + ")");
    }
    List<TimeRange> result = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        // If the fetch duration is invalid or zero, treat the whole interval as one range
        result.add(new TimeRange(start, end));
        return result;
    }
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        result.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return result;
}

