static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long compressedDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + compressedDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep<=0){
        return timeBucket;
    }
    int day = (int)(timeBucket % 100);
    int month = (int)((timeBucket / 100) % 100);
    int year = (int)(timeBucket / 10000);
    if(day<=0||day>31){
        return timeBucket;
    }
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketStartDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket; // invalid step, return original
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);
    int newDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    long compressedDay = ((day - 1) / dayStep) * dayStep + 1;
    int yearInt = (int) year;
    int monthInt = (int) month;
    // Clamp to the last valid day of the month to avoid invalid dates
    int lastDay = java.time.YearMonth.of(yearInt, monthInt).lengthOfMonth();
    int compDayInt = (int) compressedDay;
    if (compDayInt > lastDay) {
        compDayInt = lastDay;
    }
    return year * 10000 + month * 100 + compDayInt;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000L;
    long rem = timeBucket % 10000L;
    int month = (int)(rem / 100L);
    int day = (int)(rem % 100L);
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }
    final int end = index + len;
    if (index < 0 || len < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException();
    }
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            // Unpaired high surrogate
            size += 3;
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen - len) {
        throw new IllegalArgumentException("index and len must be non-negative and within string bounds");
    }
    int end = index + len;
    int size = 0;
    int pos = index;
    while (pos < end) {
        int cp = Character.codePointAt(str, pos);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        pos += Character.charCount(cp);
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || index > strLen) {
        return 0;
    }
    if (len <= 0) {
        return 0;
    }
    int end = index + len;
    if (end > strLen) {
        end = strLen;
    }
    int count = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            count += 1;
        } else if (ch < 0x800) {
            count += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            count += 4;
            i++; // skip low surrogate
        } else {
            count += 3;
        }
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null || len <= 0 || index < 0) {
        return 0;
    }
    int strLen = str.length();
    if (index > strLen) {
        return 0;
    }
    // Adjust the end index to avoid overrun
    int end = index + len;
    if (end > strLen) {
        end = strLen;
    }
    int totalBytes = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Surrogate pair -> Unicode code point > U+FFFF
            totalBytes += 4;
            i += 2;
            continue;
        }
        // Regular BMP character
        if (ch <= 0x7F) {
            totalBytes += 1;
        } else if (ch <= 0x7FF) {
            totalBytes += 2;
        } else {
            totalBytes += 3;
        }
        i++;
    }
    return totalBytes;
}

