private void enlarge(final int size) {
    // no need to enlarge if size is non-positive
    if (size <= 0) {
        return;
    }
    // compute the new capacity: double the current length or enough to fit the requested size
    int currentLength = data.length;
    long doubled = (long) currentLength * 2;
    long needed = (long) length + size;
    long newCapLong = Math.max(doubled, needed);
    // guard against overflow and set maximum possible capacity
    int newCap = (newCapLong >= Integer.MAX_VALUE) ? Integer.MAX_VALUE : (int) newCapLong;
    if (newCap <= currentLength) {
        // if the new capacity is not larger than current, just exit
        return;
    }
    try {
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    } catch (OutOfMemoryError e) {
        // wrap OOM in a RuntimeException to adhere to method signature
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
}

private void enlarge(final int size){
    if (size <= 0){
        return;
    }
    int requiredCapacity = length + size;
    int newCapacity;
    if (data == null){
        newCapacity = requiredCapacity;
    } else {
        newCapacity = Math.max(2 * data.length, requiredCapacity);
    }
    byte[] newData = new byte[newCapacity];
    if (data != null && length > 0){
        System.arraycopy(data, 0, newData, 0, length);
    }
    data = newData;
}

