@Override public int compare(Double o1, Double o2) {
    if (o1 == o2) { // covers both null or same reference
        return 0;
    }
    if (o1 == null) {
        return -1; // treat null as less than any non-null
    }
    if (o2 == null) {
        return 1; // any non-null is greater than null
    }
    // Use Double.compare to get -1, 0, or 1 according to IEEE 754
    int cmp = Double.compare(o1.doubleValue(), o2.doubleValue());
    return cmp;
}

@Override public int compare(Double o1,Double o2){
    if (o1 == null && o2 == null) return 0;
    if (o1 == null) return -1;
    if (o2 == null) return 1;
    double d1 = o1.doubleValue();
    double d2 = o2.doubleValue();
    if (Double.isNaN(d1) && Double.isNaN(d2)) return 0;
    if (Double.isNaN(d1)) return -1;
    if (Double.isNaN(d2)) return 1;
    return Integer.signum(Double.compare(d1, d2));
}

