    }
}

private boolean containsAllFields(Fields fields){
    if (fields == null) {
        return false;
    }
    // Attempt to retrieve the collection of field names from the provided `Fields` object.
    Collection<String> fieldNames;
    try {
        // If Fields exposes a method `getFields()` that returns the names.
        fieldNames = fields.getFields();
    } catch (NoSuchMethodError | UnsupportedOperationException e) {
        // Fallback: try to iterate over the Fields object directly if it implements Iterable.
        fieldNames = null;
    }
    if (fieldNames == null) {
        // If we cannot obtain the collection directly, try to use reflection to get an iterator.
        try {
            @SuppressWarnings("unchecked")
            Iterator<Object> it = (Iterator<Object>) fields.getClass().getMethod("iterator").invoke(fields);
            fieldNames = new ArrayList<>();
            while (it.hasNext()) {
                Object obj = it.next();
                if (obj instanceof java.lang.reflect.Field) {
                    fieldNames.add(((java.lang.reflect.Field) obj).getName());
                } else if (obj instanceof String) {
                    fieldNames.add((String) obj);
                } else {
                    // Unexpected type; consider as non-matching.
                    return false;
                }
            }
        } catch (Exception e) {
            // Cannot inspect the Fields object; conservatively return false.
            return false;
        }
    }
    // If fieldNames is empty, we treat it as all contained.
    if (fieldNames.isEmpty()) {
        return true;
    }
    // Now check that each field name is present in the instance's properties map.
    for (String name : fieldNames) {
        if (!properties.containsKey(name)) {
            return false;
        }
    }
    return true;
}

