public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer curr = node;
    while (curr != null) {
        out.write(curr.buf, 0, curr.count);
        total += curr.count;
        curr = curr.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer cur = node;
    while (cur != null) {
        int len = cur.pos; // number of bytes in this buffer that are actually used
        if (len > 0) {
            out.write(cur.buf, 0, len);
            totalSize += len;
        }
        cur = cur.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput is null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        if (cur.buffer == null || cur.pos <= 0) {
            continue;
        }
        out.write(cur.buffer, 0, cur.pos);
        totalSize += cur.pos;
    }
    return totalSize;
}

