public String format(final LoggingEvent event){  
    if(event==null){  
        return "";  
    }  
    try{  
        StringBuilder sb = new StringBuilder();  
        // Timestamp in milliseconds representation for simplicity  
        sb.append(event.getTimeStamp()).append(' ');  
        // Log level  
        sb.append(event.getLevel()).append(' ');  
        // Thread name  
        sb.append(event.getThreadName()).append(" - ");  
        // Logger name  
        sb.append(event.getLoggerName()).append(' ');  
        // Message (formatted if available, otherwise plain)  
        String msg = "";  
        if(event.getFormattedMessage()!=null){  
            msg = event.getFormattedMessage();  
        }else{  
            Object messageObj = event.getMessage();  
            msg = messageObj!=null?messageObj.toString():"";  
        }  
        sb.append(msg);  
        // Throwable, if present, append stack trace  
        if(event.getThrowableInformation()!=null){  
            Throwable t = event.getThrowableInformation().getThrowable();  
            if(t!=null){  
                sb.append(System.lineSeparator());  
                sb.append(t.toString()).append(System.lineSeparator());  
                for(StackTraceElement ste : t.getStackTrace()){  
                    sb.append("\tat ").append(ste.toString()).append(System.lineSeparator());  
                }  
                // Append cause chain if any  
                Throwable cause = t.getCause();  
                while(cause!=null){  
                    sb.append("Caused by: ").append(cause.toString()).append(System.lineSeparator());  
                    for(StackTraceElement ste : cause.getStackTrace()){  
                        sb.append("\tat ").append(ste.toString()).append(System.lineSeparator());  
                    }  
                    cause = cause.getCause();  
                }  
            }  
        }  
        return sb.toString();  
    }catch(Exception e){  // fallback for any unexpected problems  
        return "";  
    }  
}

