public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // start from odd number for efficiency
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        // quick checks for small candidates
        if (candidate == 2 || candidate == 3) {
            return candidate;
        }
        // skip obvious multiples to reduce work
        if ((candidate % 3) == 0 || (candidate % 5) == 0) {
            // will be handled in the loop below
        }
        boolean isPrime = true;
        // trial division up to sqrt(candidate)
        for (int i = 3; (long)i * i <= candidate; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        // avoid overflow by checking sign
        if (candidate > Integer.MAX_VALUE - 2) {
            return Integer.MAX_VALUE;
        }
        // move to next odd candidate
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        if (candidate <= 3) return candidate;
        if (candidate % 2 == 0 || candidate % 3 == 0) {
            candidate += 2;
            if (candidate <= 0) throw new IllegalArgumentException("Desired capacity too large for prime search");
            continue;
        }
        boolean isPrime = true;
        for (int i = 5; (long)i * i <= candidate; i += 6) {
            if (candidate % i == 0 || candidate % (i + 2) == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) return candidate;
        candidate += 2;
        if (candidate <= 0) throw new IllegalArgumentException("Desired capacity too large for prime search");
    }
}

