    int candidate = desiredCapacity;
    if (candidate % 2 == 0) candidate++;
    while (true) {
        boolean isPrime = true;
        if (candidate == 2) { isPrime = true; }
        else if (candidate % 2 == 0) { isPrime = false; }
        else {
            int limit = (int)Math.sqrt(candidate) + 1;
            for (int i = 3; i <= limit; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) return candidate;
        candidate += 2;
    }
}

