@Override
public String readString() throws IOException {
    // read length of the string (4 bytes, big‑endian)
    int length = readInt();
    if (length == 0) {
        return "";
    }
    if (length < 0) {
        // negative length indicates a null value
        return null;
    }
    byte[] buffer = new byte[length];
    int pos = 0;
    while (pos < length) {
        int count = in.read(buffer, pos, length - pos);
        if (count == -1) {
            throw new EOFException("Reached end of stream while reading a string");
        }
        pos += count;
    }
    return new String(buffer, StandardCharsets.UTF_8);
}

@Override public String readString() throws IOException {
    int len = readInt();
    if (len == -1) {
        return null;
    }
    if (len < 0) {
        throw new IOException("Negative string length: " + len);
    }
    byte[] buf = new byte[len];
    int pos = 0;
    while (pos < len) {
        int n = read(buf, pos, len - pos);
        if (n == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        pos += n;
    }
    return new String(buf, StandardCharsets.UTF_8);
}

