public final byte[] toByteArray(){
    try {
        if (buffer == null) {
            return new byte[0];
        }
        int remaining = buffer.remaining();
        if (remaining <= 0) {
            return new byte[0];
        }
        byte[] result;
        if (buffer.hasArray()) {
            int offset = buffer.arrayOffset() + buffer.position();
            result = new byte[remaining];
            System.arraycopy(buffer.array(), offset, result, 0, remaining);
        } else {
            buffer.mark();
            result = new byte[remaining];
            buffer.get(result);
            buffer.reset();
        }
        return result;
    } catch (Exception e) {
        return new byte[0];
    }
}

