public final byte[] toByteArray(){
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }
    int totalSize = 0;
    for (ByteArrayOutputStream bos : buffers) {
        totalSize += bos.size();
    }
    byte[] combined = new byte[totalSize];
    int offset = 0;
    for (ByteArrayOutputStream bos : buffers) {
        byte[] b = bos.toByteArray();
        System.arraycopy(b, 0, combined, offset, b.length);
        offset += b.length;
    }
    return combined;
}

