    // Copy the smaller set to reduce memory usage
    Set<V> result = set1.size() <= set2.size() ? new HashSet<>(set1) : new HashSet<>(set2);
    result.retainAll(set1.size() <= set2.size() ? set2 : set1);
    return result;
}

