protected Object filter(Object msg){
    // Return null immediately if the input message is null to avoid NullPointerException.
    if (msg == null) {
        return null;
    }
    try {
        // ``broadcastFilter`` is assumed to be a class field that implements the
        // BroadcastFilter interface with a {@code filter(Object)} method.
        if (broadcastFilter == null) {
            // No filter configured; simply return the original message.
            return msg;
        }
        // Delegate filtering to the configured BroadcastFilter instance.
        Object result = broadcastFilter.filter(msg);
        // If the filter returns null, fall back to the original message to avoid
        // unintentionally discarding data.
        return (result != null) ? result : msg;
    } catch (Throwable t) {
        // In case of any unexpected runtime exception, log or swallow silently
        // and return the original message so that the system continues to
        // operate without crash.
        return msg;
    }
}

