    if (root == null) return 0;
    int removed = 0;
    java.util.LinkedList<Category> stack = new java.util.LinkedList<>();
    stack.addFirst(root);
    while (!stack.isEmpty()){
        Category node = stack.removeFirst();
        java.util.List<Category> children = node.getChildren();
        if (children != null){
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()){
                Category child = it.next();
                if (!child.isActive()){
                    it.remove();
                    removed++;
                } else {
                    stack.addFirst(child);
                }
            }
        }
    }
    return removed;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume a field named 'root' of type Category that represents the root node of the tree
        if (root == null) {
            return 0; // nothing to remove
        }

        // If the root itself is inactive, the entire tree is removed
        if (!root.isActive()) {
            root = null;
            return 1;
        }

        // Use a stack for depth‑first traversal so that we can modify the tree safely
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            Category current = stack.pop();
            // Copy children to avoid ConcurrentModificationException
            java.util.List<Category> childrenCopy = new java.util.ArrayList<>(current.getChildren());
            for (Category child : childrenCopy) {
                if (!child.isActive()) {
                    current.removeChild(child);
                    removedCount++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // If a logger is available, log the exception; otherwise, swallow it
        try {
            LOG.error("Error while removing inactive nodes: ", e);
        } catch (Exception ignored) {
            // silent fallback
        }
    }
    return removedCount;
}

