        // If there is no root, nothing to remove
        if (root == null) {
            return 0;
        }

        // Special case: if the root itself is inactive, drop the entire tree
        if (!root.isActive()) {
            root = null;
            return 1;
        }

        // Recursively prune inactive children. The helper returns the number of nodes removed.
        removed = pruneInactive(root);
    } catch (Exception e) {
        // Log the exception or rethrow as a runtime exception
        if (LOG != null) {
            LOG.warn("Failed to remove inactive nodes", e);
        }
    }
    return removed;
}

/**
 * Recursively traverses the subtree rooted at {@code node} and removes any
 * inactive nodes from its children list.
 *
 * @param node the current node being inspected
 * @return the number of nodes removed from this subtree
 */
private int pruneInactive(Category node) {
    int count = 0;
    // Work on a copy to avoid ConcurrentModificationException
    List<Category> childrenCopy = new ArrayList<>(node.getChildren());
    for (Category child : childrenCopy) {
        count += pruneInactive(child);
    }

    // Remove this node from its parent if it is inactive
    if (!node.isActive() && node.getParent() != null) {
        node.getParent().removeChild(node);
        count += 1;
    }
    return count;
}

protected int removeUnusedNodes(){
    int removed = 0;
    if (root == null) {
        return 0;
    }
    try {
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.peek();
            java.util.List<Category> children = current.getChildren();
            if (children == null) {
                stack.pop();
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            boolean processedActive = false;
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removed++;
                } else {
                    stack.push(child);
                    processedActive = true;
                    break;
                }
            }
            if (!processedActive) {
                stack.pop();
            }
        }
    } catch (Exception e) {
        // optional logging
    }
    return removed;
}

