private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // If the start node already satisfies the predicate, immediately return it.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    Node current = start;
    // Use a simple counter to avoid infinite loops in malformed graphs.
    // In a proper planar embedding the traversal will terminate at 'stop'.
    int maxIterations = Integer.MAX_VALUE; // effectively no limit
    while (current != stop && maxIterations-- > 0) {
        Node next = current.getNextOuterFace(dir);
        if (next == null) {
            // If we can't proceed further, break to avoid NPE.
            break;
        }
        current = next;
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, dir);
        }
    }

    // Either we reached 'stop' or no node satisfied the predicate before that.
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Basic null checks – if the predicate or start node is missing, we cannot construct a useful circulator.
    if (predicate == null || start == null) {
        return null;
    }

    // Create a circulator that starts at the provided node and traverses in the requested direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Iterate along the boundary until we either find a node that satisfies the predicate
    // or reach the stop node.  The loop is guaranteed to terminate because the
    // outer face is a finite cycle: once we wrap around back to the start node the
    // traversal ends.  Using a do‑while therefore ensures the start node itself
    // is evaluated.
    for (boolean first = true; first || circ.node() != stop; first = false) {
        Node current = circ.node();
        if (predicate.test(current)) {
            return circ; // Found a suitable node – return the current circulator.
        }
        // If we have reached the stop node after checking it, we break;
        // otherwise step to the next node on the boundary.
        if (current == stop) {
            break;
        }
        circ.next(); // Advance the circulator to the next node.
    }

    // No node satisfied the predicate – the circulator is positioned on the stop node.
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        return null;
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    if (predicate.test(circ.getNode())) {
