private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    Node current = start;
    while (true) {
        // Check if current node meets the predicate
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        // If we have reached the stop node, return a circulator for it
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }
        // Advance to the next node along the outer face in the requested direction.
        // The exact method to obtain the next node depends on the library
        // but a common name is getNextOuterFace(dir) or getAdjacent(dir).
        Node next = null;
        try {
            next = current.getNextOuterFace(dir);
        } catch (NoSuchMethodError | UnsupportedOperationException e) {
            // fallback if the method name is different
            try {
                next = current.getAdjacent(dir);
            } catch (Exception ex) {
                // As a last resort, break the loop to avoid infinite looping.
                break;
            }
        }
        if (next == null || next == current) {
            // No further progress; return the circulator for the stop node
            return new OuterFaceCirculator(stop);
        }
        current = next;
    }
    // If the loop exits unexpectedly, return a circulator pointing to the stop node.
    return new OuterFaceCirculator(stop);
}

