protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (graph == null || tour == null) {
        return null;
    }
    if (tour.isEmpty()) {
        return null;
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> iter = remaining.iterator();
    if (!iter.hasNext()) {
        return null;
    }
    // start with first edge
    E startEdge = iter.next();
    iter.remove();
    V u = graph.getEdgeSource(startEdge);
    V v = graph.getEdgeTarget(startEdge);
    vertexList.add(u);
    vertexList.add(v);
    edgeList.add(startEdge);
    V current = v;
    boolean directed = graph.getType().isDirected();
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V a = graph.getEdgeSource(e);
            V b = graph.getEdgeTarget(e);
            if (directed) {
                if (current.equals(a)) {
                    vertexList.add(b);
                    edgeList.add(e);
                    current = b;
                    it.remove();
                    found = true;
                    break;
                }
            } else {
                if (current.equals(a) || current.equals(b)) {
                    V next = current.equals(a) ? b : a;
                    vertexList.add(next);
                    edgeList.add(e);
                    current = next;
                    it.remove();
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            // cannot continue forming a single tour
            break;
        }
    }
    double weight = 0.0;
    if (graph.getType().isWeighted()) {
        for (E e : edgeList) {
            weight += graph.getEdgeWeight(e);
        }
    }
    return new GraphWalk<>(graph, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) return null;
    if (tour.isEmpty()) return null;
    // Build adjacency map
    Map<V, List<E>> adj = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Start from any vertex that has degree 1 if exists, otherwise arbitrary
    V startVertex = null;
    for (Map.Entry<V, List<E>> entry : adj.entrySet()) {
        if (entry.getValue().size() == 1) {
            startVertex = entry.getKey();
            break;
        }
    }
    if (startVertex == null) {
        // no endpoint found, pick first vertex of first edge
        E firstEdge = tour.iterator().next();
        startVertex = graph.getEdgeSource(firstEdge);
    }
    V current = startVertex;
    List<E> ordered = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    while (visited.size() < tour.size()) {
        List<E> edgesAt = adj.get(current);
        if (edgesAt == null) break;
        E next = null;
        for (E e : edgesAt) {
            if (!visited.contains(e)) {
                next = e;
                break;
            }
        }
        if (next == null) break;
        ordered.add(next);
        visited.add(next);
        V src = graph.getEdgeSource(next);
        V tgt = graph.getEdgeTarget(next);
        current = src.equals(current) ? tgt : src;
    }
    if (visited.size() != tour.size()) {
        // cannot form a single contiguous tour
        return null;
    }
    V endVertex = ordered.isEmpty() ? startVertex : (graph.getEdgeSource(ordered.get(ordered.size() - 1)).equals(startVertex) ?
            graph.getEdgeTarget(ordered.get(ordered.size() - 1)) :
            graph.getEdgeSource(ordered.get(ordered.size() - 1)));
    double pathWeight = 0.0;
    for (E e : ordered) {
        pathWeight += graph.getEdgeWeight(e);
    }
    return new GraphPath<>(graph, startVertex, endVertex, ordered, pathWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()) return null;
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    Set<E> used = new HashSet<>();
    // Start with the first edge
    E firstEdge = edgeList.get(0);
    V firstSource = graph.getEdgeSource(firstEdge);
    V firstTarget = graph.getEdgeTarget(firstEdge);
    vertexList.add(firstSource);
    vertexList.add(firstTarget);
    used.add(firstEdge);
    // Build the rest of the path by attaching edges that connect to the current last vertex
    while (used.size() < edgeList.size()){
        boolean found = false;
        V lastVertex = vertexList.get(vertexList.size() - 1);
        for (E e : edgeList){
            if (used.contains(e)) continue;
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            if (s.equals(lastVertex)){
                vertexList.add(t);
                used.add(e);
                found = true;
                break;
            } else if (t.equals(lastVertex)){
                vertexList.add(s);
                used.add(e);
                found = true;
                break;
            }
        }
        if (!found){
            // The edges can't form a continuous path
            return null;
        }
    }
    // Construct and return the GraphPath (JGraphT implementation)
    return new GraphPathImpl<>(graph, vertexList, new ArrayList<>(used));
}

