private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            // handle Unicode escape \uXXXX
            if (next == 'u' || next == 'U') {
                if (i + 5 < input.length()) {
                    char h1 = input.charAt(i + 2);
                    char h2 = input.charAt(i + 3);
                    char h3 = input.charAt(i + 4);
                    char h4 = input.charAt(i + 5);
                    int d1 = Character.digit(h1, 16);
                    int d2 = Character.digit(h2, 16);
                    int d3 = Character.digit(h3, 16);
                    int d4 = Character.digit(h4, 16);
                    if (d1 != -1 && d2 != -1 && d3 != -1 && d4 != -1) {
                        sb.append((char)((d1 << 12) | (d2 << 8) | (d3 << 4) | d4));
                        i += 5; // skip \uXXXX
                        continue;
                    }
                }
            }
            // handle simple escape sequences
            switch (next) {
                case 'n': sb.append('\n'); break;
                case 't': sb.append('\t'); break;
                case 'r': sb.append('\r'); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                default: sb.append(next); // for \\, \", \'
            }
            i++; // skip the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

