    // Capture neighboring nodes
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    // Re-link previous node's next to skip the removed node
    if (prev != null) {
        prev.next = next;
    } else {
        // Node is the head of the list
        head = next;
    }

    // Re-link next node's prev to skip the removed node
    if (next != null) {
        next.prev = prev;
    } else {
        // Node is the tail of the list
        tail = prev;
    }

    // Disconnect the removed node from the list
    node.prev = null;
    node.next = null;

    // Adjust size counter, ensuring it doesn't go negative
    if (size > 0) {
        size--;
    }

    return true;
