private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    for (Integer val : bounds) {
        if (val == null) {
            throw new NullPointerException("bounds contains null element");
        }
        total += val;
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.add(0, (int) running);
    }
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Prepare result list
    List<Integer> suffixSum = new ArrayList<>();

    // Handle null or empty input
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(suffixSum, 0L);
    }

    // Calculate total sum of all elements
    long totalSum = 0L;
    for (int value : bounds) {
        totalSum += value;
    }

    // Compute suffix sums from end to start
    long runningSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        // Cast runningSum to int (may lose data if overflow, but matches signature)
        suffixSum.add(i, (int) runningSum);
    }

    return Pair.of(suffixSum, totalSum);
}

