}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int size = bounds.size();
    long totalSum = 0L;
    int[] temp = new int[size];
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null element at index " + i);
        }
        totalSum += val;
        temp[i] = (int) totalSum;
    }
    List<Integer> suffix = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        suffix.add(temp[i]);
    }
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("array cannot be null");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be <= to index");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("index out of bounds: from=" + from + " to=" + to + " length=" + arr.length);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

