    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", length=" + len);
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Guard against null and moving from itself
    if (list == null || list == this) {
        return;
    }

    // Grab the first node; if the list has no nodes nothing to do
    ListNode<E> current = list.getFirstNode();
    while (current != null) {
        // Save the next node before removal to avoid losing the reference
        ListNode<E> next = current.getNext();

        // Remove from the source list
        removeListNode(current);

        // Add to this list
        addListNode(current);

        // Continue with the next node from the original list
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new NullPointerException("list");
    }
    if (list == this) {
        return;
    }
    // If the source list is empty, nothing to move
    if (list.first == null) {
        return;
    }
    // Save source list references
    Node<E> otherFirst = list.first;
    Node<E> otherLast = list.last;
    int otherSize = list.size;
    // Link the nodes into the current list
    if (this.first == null) {
        // Current list is empty: just adopt the other's nodes
        this.first = otherFirst;
        this.last = otherLast;
    } else {
        // Current list non‑empty: glue at the end
        this.last.next = otherFirst;
        otherFirst.prev = this.last;
        this.last = otherLast;
    }
    // Update size and modCount of the current list
    this.size += otherSize;
    this.modCount++;
    // Clear the source list
    list.first = null;
    list.last = null;
    list.size = 0;
    list.modCount++;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) return;
    ListNode<E> cur = list.getFirst();
    while (cur != null) {
        ListNode<E> next = cur.getNext();
        list.removeListNode(cur);
        addListNode(cur);
        cur = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this || list.size == 0) {
        return;
    }
    // Keep the number of nodes being moved
    int movedSize = list.size;

    // Grab the first and last nodes of the source list
    ListNode<E> srcFirst = list.head;
    ListNode<E> srcLast  = list.tail;

    // Detach source list completely
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Attach the source nodes to this list
    if (this.head == null) {
        // Destination list is empty – just adopt the source list
        this.head = srcFirst;
        this.tail = srcLast;
    } else {
        // Destination list already has nodes – link the ends
        this.tail.next  = srcFirst;
        srcFirst.prev   = this.tail;
        this.tail       = srcLast;
    }

    // Update the size of the destination list
    this.size += movedSize;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null && prefix == null) {
        return true;
    }
    if (str == null || prefix == null) {
        return false;
    }
    if (prefix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase){
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    if (prefix.length() > str.length()) {
        return false;
    }
    if (!ignoreCase) {
        return str.startsWith(prefix);
    }
    for (int i = 0; i < prefix.length(); i++) {
        char c1 = str.charAt(i);
        char c2 = prefix.charAt(i);
        if (Character.toLowerCase(c1) != Character.toLowerCase(c2)) {
            return false;
        }
    }
    return true;
}

