public int decide(LoggingEvent event){  
    // Defensive null checks  
    if (event == null) {  
        return Filter.NEUTRAL;  
    }  

    Object msgObj = event.getMessage();  
    if (!(msgObj instanceof String)) {  
        return Filter.NEUTRAL;  
    }  

    String message = (String) msgObj;  
    if (message == null) {  
        return Filter.NEUTRAL;  
    }  

    // If a filter string is defined and the message contains it, accept the event.  
    // The field `filterString` is assumed to be defined elsewhere in the class.  
    if (filterString != null && message.contains(filterString)) {  
        return Filter.ACCEPT;  
    }  

    // No match – return neutral.  
    return Filter.NEUTRAL;  
}

public int decide(LoggingEvent event){
    if(event == null){
        return Filter.NEUTRAL;
    }
    String message = event.getFormattedMessage();
    if(message == null){
        return Filter.NEUTRAL;
    }
    try{
        for(Pattern pattern : patterns){
            if(pattern.matcher(message).find()){
                return Filter.DENY;
            }
        }
    }catch(RuntimeException e){
        // In case of any regex error, treat as neutral
    }
    return Filter.NEUTRAL;
}

