public void putAllWriteable(BeanMap map){  
    if (map == null) {  
        return;  
    }  
    for (Object keyObj : map.keySet()){  
        if (keyObj == null) { continue; }  
        String key = keyObj.toString();  
        if (!map.isReadable(key)) {  
            continue;  
        }  
        if (!this.isWritable(key)) {  
            continue;  
        }  
        Object value = map.get(key);  
        this.put(key, value);  
    }  
}

public void putAllWriteable(BeanMap map){
    if (map == null){
        throw new IllegalArgumentException("mapped BeanMap must not be null");
    }
    // Iterate over each property exposed by the source map
    for (String propName : map.keySet()){
        try {
            // Only copy if the source has a readable value and this map accepts writes
            if (map.isReadable(propName) && this.isWritable(propName)){
                Object value = map.get(propName);
                this.set(propName, value);
            }
        }catch (Exception e){
            // Silently ignore properties that cannot be accessed or set
        }
    }
}

public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    for (Object keyObj : map.keySet()) {
        if (!(keyObj instanceof String)) {
            continue;
        }
        String key = (String) keyObj;
        try {
            // Ensure the property is readable in the source map
            if (map.getReadMethod(key) == null) {
                continue;
            }
            // Ensure the property is writable in this (destination) map
            if (this.getWriteMethod(key) == null) {
                continue;
            }
            Object value = map.get(key);
            this.put(key, value);
        } catch (Exception e) {
            // Ignore problems related to reflection or type mismatches
        }
    }
}

