    // Guard against null references
    if (table == null || pane == null) {
        return;
    }

    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        // Row index out of bounds; nothing to do
        return;
    }

    // Select the desired row
    table.setRowSelectionInterval(row, row);

    // Scroll to the row so the selected row is visible
    java.awt.Rectangle rect = table.getCellRect(row, 0, true);
    if (rect != null) {
        table.scrollRectToVisible(rect);
    }

    // Delay repaint slightly to ensure selection is painted correctly
    javax.swing.Timer timer = new javax.swing.Timer(200, e -> {
        pane.repaint();
