private void pop(final String descriptor){
    if (descriptor == null) throw new IllegalArgumentException("descriptor cannot be null");
    int i = 0;
    final int len = descriptor.length();
    // If method descriptor, skip parameter part inside parentheses
    if (i < len && descriptor.charAt(i) == '(') {
        i++; // skip '('
        while (i < len) {
            char c = descriptor.charAt(i);
            if (c == ')') {
                i++; // skip ')'
                break;
            }
            // Parse a single type
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) throw new IllegalArgumentException("Malformed descriptor: missing ';'");
                // reference type occupies one slot
                pos--;
                i = semicolon + 1;
            } else if (c == '[') {
                // array: consume all '[' and the element type
                while (i < len && descriptor.charAt(i) == '[') i++;
                if (i >= len) throw new IllegalArgumentException("Malformed descriptor: array type incomplete");
                // element type (could be reference or primitive)
                if (descriptor.charAt(i) == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) throw new IllegalArgumentException("Malformed descriptor: missing ';' after array element");
                    // array of reference
                    pos--;
                    i = semicolon + 1;
                } else {
                    // array of primitive: array type is reference, occupies one slot
                    pos--;
                    // skip primitive descriptor
                    i++;
                }
            } else {
                // primitive type
                boolean twoSlots = (c == 'J' || c == 'D');
                pos--;
                if (twoSlots) pos--;
                i++;
            }
        }
    } else {
        // Normal type descriptor: single type
        if (i >= len) throw new IllegalArgumentException("Malformed descriptor: empty");
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) throw new IllegalArgumentException("Malformed descriptor: missing ';'");
            pos--;
            i = semicolon + 1;
        } else if (c == '[') {
            while (i < len && descriptor.charAt(i) == '[') i++;
            if (i >= len) throw new IllegalArgumentException("Malformed descriptor: array type incomplete");
            if (descriptor.charAt(i) == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) throw new IllegalArgumentException("Malformed descriptor: missing ';' after array element");
                pos--;
                i = semicolon + 1;
            } else {
                pos--;
                i++;
            }
        } else {
            boolean twoSlots = (c == 'J' || c == 'D');
            pos--;
            if (twoSlots) pos--;
            i++;
        }
        if (i != len) {
            throw new IllegalArgumentException("Malformed descriptor: unexpected trailing characters");
        }
    }
}

