public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath == null ? null : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        // Return original path if relative path is empty or null
        return path;
    }

    // Split the base path and create a stack of components
    String[] baseParts = path.split("/", -1);
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String part : baseParts) {
        stack.addLast(part);
    }

    // Split the relative path and apply each component
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // No effect on stack
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    String result = String.join("/", stack);
    // Handle special cases: root or empty result
    if (result.isEmpty()) {
        // If the original path starts with '/', preserve root
        return path.startsWith("/") ? "/" : ".";
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    // Handle null or empty cases
    if (path == null || path.isEmpty()) {
        return relativePath == null ? "" : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // If relativePath starts with a slash, treat as absolute and return it directly
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the base path and the relative path into components
    String[] baseSegments = path.split("/");
    String[] relSegments = relativePath.split("/");

    // Use a list to build the resulting path segments
    java.util.List<String> resultSegments = new java.util.ArrayList<>();

    // Preserve leading slash information
    boolean leadingSlash = path.startsWith("/");

    // Add non-empty segments from the base path
    for (String seg : baseSegments) {
        if (!seg.isEmpty()) {
            resultSegments.add(seg);
        }
    }

    // Process relative path segments
    for (String seg : relSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            // Skip empty or current-directory references
            continue;
        } else if (seg.equals("..")) {
            // Go up one directory if possible
            if (!resultSegments.isEmpty()) {
                resultSegments.remove(resultSegments.size() - 1);
            }
        } else {
            // Normal segment, add to the list
            resultSegments.add(seg);
        }
    }

    // Construct the final path string
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < resultSegments.size(); i++) {
        result.append(resultSegments.get(i));
        if (i < resultSegments.size() - 1) {
            result.append("/");
        }
    }

    // If result is empty and the original path was absolute, return "/"
    if (result.length() == 0 && leadingSlash) {
        return "/";
    }

    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
