    }
    // Normalize separators to forward slash
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');
    String base;
    if (path.endsWith("/")) {
        base = path;
    } else {
        int idx = path.lastIndexOf('/');
        base = (idx >= 0) ? path.substring(0, idx + 1) : "";
    }
    String combined;
    if (relativePath.startsWith("/")) {
        combined = relativePath;
    } else {
        combined = base.isEmpty() ? relativePath : base + relativePath;
    }
    try {
        java.nio.file.Path resolvedPath = java.nio.file.Paths.get(combined).normalize();
        return resolvedPath.toString().replace('\\', '/');
    } catch (Exception e) {
        // fallback: return combined if normalization fails
        return combined;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    if (relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Normalize the base path
    for (String seg : path.split("/")) {
        if (seg == null || seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }

    // Apply the relative path
    for (String seg : relativePath.split("/")) {
        if (seg == null || seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }

    // Build the final path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    String finalPath = result.toString();
    if (finalPath.isEmpty()) {
        finalPath = isAbsolute ? "/" : ".";
    }
    return finalPath;
}

