    // If a directory separator occurs after the last dot, the dot is not part of the file name
    if (lastSep > lastDot) {
        return -1;
    }
    return lastDot;
}

public static int indexOfExtension(String filename){
    if (filename == null) return -1;
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) return -1;
    int lastSep = indexOfLastSeparator(filename);
    if (lastSep > lastDot) return -1;
    return lastDot;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (timestamp <= 0) {
        return false;
    }
    if (expiredThreshold <= 0) {
        return false;
    }
    long now = System.currentTimeMillis();
    long diff = now - timestamp;
    return diff > expiredThreshold;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (expiredThreshold == -1L) {
        return false;
    }
    if (timestamp <= 0L || expiredThreshold <= 0L) {
        return false;
    }
    try {
        return System.currentTimeMillis() - timestamp > expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (expiredThreshold <= 0) return false;
    long now = System.currentTimeMillis();
    return now - timestamp >= expiredThreshold;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold < 0) {
        return false; // never expire
    }
    long now = System.currentTimeMillis();
    return now - timestamp > expiredThreshold;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    // Handle invalid threshold values; non-positive thresholds mean never expire
    if (expiredThreshold < 0) {
        return false;
    }
    // Current time at check moment
    long now = System.currentTimeMillis();
    // If the elapsed time since the provided timestamp exceeds the threshold, consider it expired
    return now - timestamp > expiredThreshold;
}

