    Node from = this._prev.isVirtual() ? this._prev.getReal() : this._prev;
    Node to   = this._next.isVirtual() ? this._next.getReal() : this._next;
    // Search for an edge connecting the two nodes
    for (Edge e : this._edges) {
        if (e.getFrom() == from && e.getTo() == to) {
