}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null || substring==null) return false;
    int lenStr = str.length();
    int lenSub = substring.length();
    if(index<0 || index>lenStr) return false;
    if(lenSub==0){
        return index==lenStr || index<=lenStr;
    }
    if(index+lenSub>lenStr) return false;
    for(int i=0;i<lenSub;i++){
        if(str.charAt(index+i)!=substring.charAt(i)) return false;
    }
    return true;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null||substring==null){
        return false;
    }
    int lenSub = substring.length();
    if(index<0 || index>str.length()){
        return false;
    }
    // If substring is empty, it matches any index within bounds
    if(lenSub==0){
        return true;
    }
    if(index+lenSub>str.length()){
        return false;
    }
    for(int i=0;i<lenSub;i++){
        if(str.charAt(index+i)!=substring.charAt(i)){
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen - subLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    // Return false if either argument is null
    if (str == null || substring == null) {
        return false;
    }
    // Negative index is invalid
    if (index < 0) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    // Substring longer than the remaining part of 'str' from index
    if (index > strLen - subLen) {
        return false;
    }
    // Empty substring always matches at any valid index
    if (subLen == 0) {
        return true;
    }
    // Compare character by character
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

