    while (true) {
        if (pos == count) {
            fillBuf();
            if (pos == count) {
                return 0; // EOF reached
            }
        }
        int b = buf[pos++] & 0xFF;
        temp |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return temp;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint while reading tag");
        }
    }
}

