    return "bytes */*";
}

private String buildContentRange(){
    // The following fields are expected to be present in the surrounding class:
    // long rangeStart, rangeEnd, and long contentLength.
    // If any of these are not initialized correctly, we return null.
    if (rangeStart < 0L || rangeEnd < 0L || contentLength <= 0L) {
        return null;
    }
    return "bytes " + rangeStart + "-" + rangeEnd + "/" + contentLength;
}

private String buildContentRange() {
    // Expected instance variables: long contentRangeStart, contentRangeEnd, contentLength
    // Validate fields before constructing the header value
    if (contentRangeStart < 0 || contentRangeEnd < contentRangeStart || contentLength <= 0) {
        return null;
    }
    return String.format("bytes %d-%d/%d", contentRangeStart, contentRangeEnd, contentLength);
}

private String buildContentRange(){
    // Construct the Content-Range header using start, end, and total length.
    // Assumes the containing class has member variables: 
    //   Long startByte, endByte, contentSize (or similar). 
    // If any of these are null or invalid, return null.
    long start = 0L;
    long end = 0L;
    Long total = null;
    try {
        // Attempt to read fields if they exist; otherwise use defaults.
        java.lang.reflect.Field startField = this.getClass().getDeclaredField("startByte");
        java.lang.reflect.Field endField = this.getClass().getDeclaredField("endByte");
        java.lang.reflect.Field totalField = this.getClass().getDeclaredField("contentSize");

        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);

        Object startVal = startField.get(this);
        Object endVal = endField.get(this);
        Object totalVal = totalField.get(this);

        if (startVal == null || endVal == null) {
            return null;
        }

        start = ((Number) startVal).longValue();
        end = ((Number) endVal).longValue();

        if (totalVal != null && totalVal instanceof Number) {
            total = ((Number) totalVal).longValue();
        }
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // Fields not present; cannot build proper range.
        return null;
    } catch (ClassCastException e) {
        // Field values not numeric; cannot build proper range.
        return null;
    }

    if (start > end || start < 0) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    sb.append("bytes ").append(start).append("-").append(end).append("/");
    sb.append(total != null && total > 0 ? total : "*");
    return sb.toString();
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
