        return result;
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            try {
                ThreadSnapshot snapshot = new ThreadSnapshot(line);
                result.add(snapshot);
            } catch (Exception e) {
                // Ignore malformed entries
            }
        }
    }
    return result;
}

public static java.util.List<ThreadSnapshot> parseFromFileWithTimeRange(java.io.File file, java.util.List<ProfileAnalyzeTimeRange> timeRanges) throws java.io.IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.isFile()) {
        return result;
    }
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                // Assume ThreadSnapshot has a static factory method that parses a line representation
                ThreadSnapshot snapshot = ThreadSnapshot.fromString(line);
                if (timeRanges == null || timeRanges.isEmpty()) {
                    result.add(snapshot);
                    continue;
                }
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartMillis();
                    long end = range.getEndMillis();
                    long ts = snapshot.getTimestamp();
                    if (ts >= start && ts <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (inRange) {
                    result.add(snapshot);
                }
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a ThreadSnapshot
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static method to parse from a line
                snapshot = ThreadSnapshot.parseFrom(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed
                continue;
            }
            long ts = snapshot.getTimestamp(); // Assume snapshot has a getTimestamp method
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (ts >= range.getStartMillis() && ts <= range.getEndMillis()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("file does not exist or is not a regular file: " + file);
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                // Assumes CSV format: timestamp,otherData
                String[] parts = line.split(",", 2);
                long timestamp = Long.parseLong(parts[0].trim());
                boolean withinRange = true;
                if (timeRanges != null && !timeRanges.isEmpty()) {
                    withinRange = false;
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                            withinRange = true;
                            break;
                        }
                    }
                }
                if (!withinRange) {
                    continue;
                }
                ThreadSnapshot snapshot;
                if (parts.length > 1) {
                    snapshot = new ThreadSnapshot(timestamp, parts[1].trim());
                } else {
                    snapshot = new ThreadSnapshot(timestamp);
                }
                snapshots.add(snapshot);
            } catch (NumberFormatException e) {
                // Skip lines that don't contain a valid timestamp
                continue;
            }
        }
    }
    return snapshots;
}
